var i=`0887-kottu-roti`;var n=`world-0887`;var o=`LK`;var s=`south-asia`;var a=4;var r=83;var d={en:`Kottu Roti`,ua:`Котту роті`};var g={en:`Kottu Roti is a Sri Lanka dish made with all-purpose flour, yellow onion, serrano pepper, carrot. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Котту роті, страва кухні країни Шрі-Ланка. Основні складники: пшеничне борошно універсальне, жовта цибуля, перець серрано, морква. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,320,`g`],[`water`,190,`ml`],[`table-salt`,5,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`coconut-oil`,25,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,170,`g`],[`serrano-pepper`,2,`pcs`],[`carrot`,165,`g`],[`white-cabbage`,160,`g`],[`ground-turmeric`,4,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 12 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 12 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:12,i:[[`chicken-thigh`,420,`g`],[`light-soy-sauce`,40,`ml`],[`chicken-egg`,3,`pcs`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,18,`g`]]}];var u={slug:i,id:n,country:`LK`,region:s,servings:4,minutes:83,title:d,text:g,steps:h};export{o as country,u as default,n as id,r as minutes,s as region,a as servings,i as slug,h as steps,g as text,d as title};